import React from "react";
import { motion } from "framer-motion";

const Home = ({ darkMode }) => {
    const services = [
        { title: "Floor Planning", desc: "Strategic space management for maximum flow.", icon: "📐" },
        { title: "Vendor Sourcing", desc: "Connecting you with top-tier booth builders.", icon: "🤝" },
        { title: "Digital Integration", desc: "Hybrid event solutions and custom event apps.", icon: "🌐" },
    ];

    return React.createElement("main", null,
        // Services Section
        React.createElement("section", { className: "py-20 px-8 max-w-7xl mx-auto" },
            React.createElement("div", { className: "grid md:grid-cols-3 gap-8" },
                services.map((service, index) =>
                    React.createElement(motion.div, {
                        key: index,
                        whileHover: { y: -10 },
                        className: `p-10 rounded-3xl border ${darkMode ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"
                            } shadow-2xl transition-all group`
                    },
                        React.createElement("div", { className: "text-4xl mb-4 group-hover:scale-125 transition-transform inline-block" }, service.icon),
                        React.createElement("h4", { className: "text-2xl font-bold mb-3" }, service.title),
                        React.createElement("p", { className: "opacity-60 leading-relaxed" }, service.desc),
                        React.createElement(motion.div, {
                            className: "mt-6 h-1 w-0 bg-blue-500 group-hover:w-full transition-all duration-500"
                        })
                    )
                )
            )
        ),
        // Stats Section
        React.createElement("section", {
            className: `py-16 ${darkMode ? "bg-gray-800/50" : "bg-blue-600"} text-white text-center`
        },
            React.createElement("div", { className: "grid md:grid-cols-3 gap-10 max-w-5xl mx-auto" },
                [
                    { val: "500+", label: "Events Managed" },
                    { val: "12M+", label: "Attendees Yearly" },
                    { val: "Global", label: "24 Country Reach" }
                ].map((stat, i) =>
                    React.createElement("div", { key: i },
                        React.createElement("div", { className: "text-5xl font-black" }, stat.val),
                        React.createElement("div", { className: "opacity-70" }, stat.label)
                    )
                )
            )
        )
    );
};

export default Home;
